-- Audited one-time source repair. Proof: work/high1-focus-review-20261001/provenance-verification.json.
-- Each parent is a visually checked original top-level choice question, independently
-- re-extracted from the user's ZIP; original DOCX hash + original block reproduces source_key.
-- Active source rows are immutable, so use audited revisions, never bypass their guard.
begin;
set local statement_timeout='55s';
select pg_advisory_xact_lock(hashtextextended('chem-source-original-release',0));
select pg_advisory_xact_lock(hashtextextended('chem-h3-original-release',0));
create temporary table h1_parent_review_input as select * from jsonb_to_recordset($proof$[{"old_id": "QH1O_008AC0309A70_2D0B8ED6C6ED2345_BFB3AF4B7E1A43E2", "new_id": "QH1PARENT01_2D0B8ED6C6ED2345", "source_key": "2d0b8ed6c6ed2345408c70e9e4fd7af3c9a08deb7665c260773b0a59667de2b5", "expected_revision": "bfb3af4b7e1a43e2811aa6b685b86c479a0ecc12bed725823db66a65afeec97c", "source_document_sha256": "d22df222f96f42c6f90e03fd1d44a4c9d29246838ac3acbf4a29cada7321b57f", "source_title": "2.1 研究物质的实验方法 第1课时 实验安全与基本规范 物质的分离提纯（讲义）", "block": 292, "question_no": "2", "concept_key": "H1_MATERIAL_EXPERIMENT__C02", "skill_id": "H1_MATERIAL_EXPERIMENT", "correct_option": 1, "canonical_source_id": "H1M_20260912_28_0292", "question_sha": "64d21a799a6babc0d4cdb7779df71a9ee9c02f15997711159c57cc15111247a0", "analysis_sha": "44adfc8d4412f889e6cbebd78d34aa12b5a56612de7656fda705a200f281c0af", "date": "2026-10-13"}, {"old_id": "QH1O_008AC0309A70_BE643D1EF9CEE6C9_E86236529B0F87B2", "new_id": "QH1PARENT01_BE643D1EF9CEE6C9", "source_key": "be643d1ef9cee6c9c45355c4b5c124b12f0d3676e54e7828d92c34df3ff608a8", "expected_revision": "e86236529b0f87b29e3e9925f3dbddcfdd87dc2e7bc2362fcc1bd77cbb2e5e46", "source_document_sha256": "a5be244d5b21fe6ccf4d03198cb3e03b94f96ffe25eb83a818f186ab62cd10cf", "source_title": "2.1 研究物质的实验方法 第2课时物质的检验 物质性质和变化的探究（讲义）", "block": 24, "question_no": "2", "concept_key": "H1_MATERIAL_EXPERIMENT__C03", "skill_id": "H1_MATERIAL_EXPERIMENT", "correct_option": 2, "canonical_source_id": "H1M_20260912_29_0024", "question_sha": "df4475ff6775acd039984c97b7b7fab168143ed2d25204503523fd22224dc69d", "analysis_sha": "43933638dbaa16bb4e872567f82e37a521fa1ff8f76b4b57edd0d8294a7f9e3c", "date": "2026-10-14"}, {"old_id": "QH1O_008AC0309A70_EAF64C3C95DE0FC5_8D679CD06B224153", "new_id": "QH1PARENT01_EAF64C3C95DE0FC5", "source_key": "eaf64c3c95de0fc54459986415a9bcb629c5dbdcbbc0dd6444b2f50da2f8b72b", "expected_revision": "8d679cd06b224153b87d750e0a1e2b7511054d603aabd19f10c98678148556eb", "source_document_sha256": "a5be244d5b21fe6ccf4d03198cb3e03b94f96ffe25eb83a818f186ab62cd10cf", "source_title": "2.1 研究物质的实验方法 第2课时物质的检验 物质性质和变化的探究（讲义）", "block": 348, "question_no": "1", "concept_key": "H1_MATERIAL_EXPERIMENT__C04", "skill_id": "H1_MATERIAL_EXPERIMENT", "correct_option": 1, "canonical_source_id": "H1M_20260912_29_0348", "question_sha": "a17b71dc71c4d8762d7ac3954e1fa42ae5bddd72a6ee6086995b73ff1e153045", "analysis_sha": "438b15d1f77a5434d77f5e7dc24e00bf668aed0b126c141fb66f49c093997b1a", "date": "2026-10-15"}, {"old_id": "QH1O_008AC0309A70_C46123AB8F30CF4F_224CBCA4EC1EF103", "new_id": "QH1PARENT01_C46123AB8F30CF4F", "source_key": "c46123ab8f30cf4f5c122677d02afbe55bd9e852a6c24630cd910ad7f8496fca", "expected_revision": "224cbca4ec1ef103917618effa669a06f48a6a168ef61e34119d5ae35e10d025", "source_document_sha256": "a5be244d5b21fe6ccf4d03198cb3e03b94f96ffe25eb83a818f186ab62cd10cf", "source_title": "2.1 研究物质的实验方法 第2课时物质的检验 物质性质和变化的探究（讲义）", "block": 359, "question_no": "2", "concept_key": "H1_MATERIAL_EXPERIMENT__C05", "skill_id": "H1_MATERIAL_EXPERIMENT", "correct_option": 1, "canonical_source_id": "H1M_20260912_29_0359", "question_sha": "201cd7c1a0c08a2a391ca483ef2f71eb7cb4e6ff87cdb97648817c30ea0f5617", "analysis_sha": "198ed80354dba64f30e8378cc18e2217c9f59932d28b18cea0f7508fd903bdad", "date": "2026-10-16"}, {"old_id": "QH1O_008AC0309A70_50E78752D3204B0A_7F9D2B93E110942B", "new_id": "QH1PARENT01_50E78752D3204B0A", "source_key": "50e78752d3204b0ae2487db0d74685ca478a8a0096d4d2df2aaf198ba3cdf9be", "expected_revision": "7f9d2b93e110942b9c34f9aebee9065abac0a7199ef5c1ff673510d300c1dd79", "source_document_sha256": "443c515fb9322006358341360a242a2252af5fa6600f8705f06b1468bc9ba091", "source_title": "3.2 金属钠与钠的化合物 第3课时 离子反应（讲义）", "block": 572, "question_no": "1", "concept_key": "H1_ELECTROLYTE__C54", "skill_id": "H1_ELECTROLYTE", "correct_option": 2, "canonical_source_id": "H1M_20260912_59_0572", "question_sha": "716a1f70a0a67f9bf15955bca0da54fa06b9b2e007a8182bd6e730507a8a5b55", "analysis_sha": "2049c6a0b109c046832400d15df445866bd978cb8e1e47caf609209274a03e00", "date": "2026-10-05"}]$proof$::jsonb)
 as x(old_id text,new_id text,source_key text,expected_revision text,source_document_sha256 text,source_title text,block integer,question_no text,concept_key text,skill_id text,correct_option integer,canonical_source_id text,question_sha text,analysis_sha text,date date);
select q.id from public.chem_questions q join h1_parent_review_input x on x.old_id=q.id order by q.id for update of q;
create temporary table h1_parent_old_questions as select q.id,to_jsonb(q)-array['usable_for_review','usable_for_class_quiz','usable_for_exam_sprint','usable_for_demo','updated_at'] row_data from public.chem_questions q join h1_parent_review_input x on x.old_id=q.id;
create temporary table h1_parent_old_answers as select a.* from public.chem_attempt_answers a join h1_parent_review_input x on x.old_id=a.question_id;
create temporary table h1_parent_old_locks as select a.* from app_private.chem_question_answer_locks a join h1_parent_review_input x on x.old_id=a.question_id;
do $guard$ begin
 if (select count(*) from h1_parent_old_questions)<>5 or exists(select 1 from app_private.chem_question_source_releases where id='ce52b904-0d33-48b1-9d75-e3b20e48b31f') then raise exception 'Baseline missing or repair already applied';end if;
 if exists(select 1 from public.chem_questions q join h1_parent_review_input x on x.old_id=q.id where
   q.question_revision_token<>x.expected_revision or q.source_item_key<>x.source_key or q.parent_source_item_key is not null
   or q.source_release_id<>'8da16477-6e5e-59bd-9065-279d28c62b30' or q.concept_key<>x.concept_key or q.correct_option<>x.correct_option
   or x.source_key<>encode(extensions.digest('docx:'||x.source_document_sha256||'|questionStartBlock:'||x.block,'sha256'),'hex')) then raise exception 'Reviewed source identity changed';end if;
 if exists(select 1 from h1_parent_review_input x where not exists(select 1 from app_private.chem_teaching_ready_questions q where q.id=x.old_id)) then raise exception 'Old reviewed source is no longer ready';end if;
 if exists(select 1 from h1_parent_review_input x where
   not exists(select 1 from app_private.chem_question_assets a where a.question_id=x.old_id and a.asset_kind='question_image' and a.sha256=x.question_sha)
   or not exists(select 1 from app_private.chem_question_assets a where a.question_id=x.old_id and a.asset_kind='analysis_image' and a.sha256=x.analysis_sha)) then raise exception 'Visually verified asset changed';end if;
 if exists(select 1 from public.chem_questions q join h1_parent_review_input x on q.id=x.new_id or q.parent_source_item_key=x.source_key) then raise exception 'An existing parent revision needs reconciliation';end if;
end $guard$;
insert into app_private.chem_question_delivery_holds(anchor_question_id,reason)
select old_id,'2026-10-01 DOCX原件顶层题身份已核验；旧导入缺少parent身份，保留历史，改用明确原始母题的新修订。题干、选项和答案不变。' from h1_parent_review_input;
insert into app_private.chem_question_source_releases(id,manifest_sha256,grade_band,status,expected_question_count,verification_status,revision_contract,release_kind)
values('ce52b904-0d33-48b1-9d75-e3b20e48b31f',encode(extensions.digest('h1-source-parent-proof-20261001','sha256'),'hex'),'高一','staged',5,'pending','v2_explanation_assets','teaching_material');
insert into public.chem_questions
select (jsonb_populate_record(null::public.chem_questions,to_jsonb(q)||jsonb_build_object(
 'id',x.new_id,'source_release_id','ce52b904-0d33-48b1-9d75-e3b20e48b31f','mother_id','MH1PARENT01_'||upper(substr(x.source_key,1,16)),
 'source_item_key',encode(extensions.digest(x.source_key||'|parent-proof-20261001','sha256'),'hex'),'parent_source_item_key',x.source_key,
 'usable_for_review',false,'usable_for_class_quiz',false,'usable_for_exam_sprint',false,'usable_for_demo',false,
 'source_info',q.source_info||jsonb_build_object('questionNo',x.question_no,'locator','已核验原DOCX SHA256 '||x.source_document_sha256||' · 顶层题起点 block '||x.block,
   'transcriptionAuditMethod','Original ZIP/DOCX identity, whole original choice, original teacher explanation and current sealed assets individually verified 2026-10-01'),
 'asset_refs',(select jsonb_agg(ref||jsonb_build_object('path','h1parent20261001/'||lower(x.new_id)||'/'||(ref->>'kind')) order by ref->>'kind') from jsonb_array_elements(q.asset_refs) ref),
 'created_at',now(),'updated_at',now()))).*
from public.chem_questions q join h1_parent_review_input x on x.old_id=q.id;
insert into app_private.chem_question_assets(asset_path,question_id,asset_kind,mime_type,payload_base64,sha256,width,height)
select 'h1parent20261001/'||lower(x.new_id)||'/'||a.asset_kind,x.new_id,a.asset_kind,a.mime_type,a.payload_base64,a.sha256,a.width,a.height
from app_private.chem_question_assets a join h1_parent_review_input x on x.old_id=a.question_id;
update public.chem_questions q set question_revision_token=app_private.chem_h3_question_revision_sha256(q,a.sha256,b.sha256)
from app_private.chem_question_assets a,app_private.chem_question_assets b where q.source_release_id='ce52b904-0d33-48b1-9d75-e3b20e48b31f' and a.question_id=q.id and a.asset_kind='question_image' and b.question_id=q.id and b.asset_kind='analysis_image';
insert into app_private.chem_question_source_release_items(release_id,question_id,canonical_source_id,question_asset_sha256,analysis_asset_sha256,item_sha256)
select 'ce52b904-0d33-48b1-9d75-e3b20e48b31f',q.id,x.canonical_source_id,a.sha256,b.sha256,app_private.chem_h3_release_item_sha256(q,x.canonical_source_id,a.sha256,b.sha256)
from public.chem_questions q join h1_parent_review_input x on x.new_id=q.id join app_private.chem_question_assets a on a.question_id=q.id and a.asset_kind='question_image' join app_private.chem_question_assets b on b.question_id=q.id and b.asset_kind='analysis_image';
update app_private.chem_question_source_releases r set manifest_sha256=(select encode(extensions.digest(convert_to(string_agg(i.item_sha256,E'\n' order by i.question_id),'UTF8'),'sha256'),'hex') from app_private.chem_question_source_release_items i where i.release_id=r.id) where id='ce52b904-0d33-48b1-9d75-e3b20e48b31f';
select public.chem_record_question_item_visual_review(q.id,q.question_revision_token,q.source_info->>'locator','codex-source-parent-audit-20261001',
 '2026-10-01 原ZIP恢复DOCX，SHA256='||x.source_document_sha256||'，第'||x.block||'块开始的独立顶层选择题，原题号'||x.question_no||'。原文四选项和原教师答案、现行封装题图与解析图逐项核验，唯一答案'||substr('ABCD',x.correct_option+1,1)||'。题干、选项和解析文字未改动，仅明确原始母题身份；不是新编题或一个大题拆出的独立母题。',
 '{"stem_options_and_formula":true,"answer_and_explanation":true,"source_image_complete":true,"source_locator_matches":true}'::jsonb)
from public.chem_questions q join h1_parent_review_input x on x.new_id=q.id;
insert into app_private.chem_question_source_release_lineage(release_id,question_id,previous_release_id,previous_question_id)
select 'ce52b904-0d33-48b1-9d75-e3b20e48b31f',x.new_id,q.source_release_id,q.id from public.chem_questions q join h1_parent_review_input x on x.old_id=q.id;
select public.chem_mark_source_original_release_visually_verified('ce52b904-0d33-48b1-9d75-e3b20e48b31f',(select manifest_sha256 from app_private.chem_question_source_releases where id='ce52b904-0d33-48b1-9d75-e3b20e48b31f'),'codex-full-visual-qa');
select * from public.chem_activate_teaching_material_release('ce52b904-0d33-48b1-9d75-e3b20e48b31f',(select manifest_sha256 from app_private.chem_question_source_releases where id='ce52b904-0d33-48b1-9d75-e3b20e48b31f'));
insert into app_private.chem_teaching_question_topics(question_id,topic_id,evidence)
select x.new_id,t.topic_id,jsonb_build_object('method','visually_verified_revision_lineage','evidence',jsonb_build_object('parentQuestionId',x.old_id,'sourceReleaseId','ce52b904-0d33-48b1-9d75-e3b20e48b31f','sourceLocator',q.source_info->>'locator','sourceDocumentSha256',x.source_document_sha256,'basis','unchanged original question, DOCX top-level parent provenance restored'),'sameTypeClaim',false,'questionRevisionToken',q.question_revision_token)
from h1_parent_review_input x join app_private.chem_teaching_question_topics t on t.question_id=x.old_id join public.chem_questions q on q.id=x.new_id;
do $qa$ begin
 if exists(select 1 from public.chem_questions n join h1_parent_review_input x on x.new_id=n.id join public.chem_questions o on o.id=x.old_id
   where n.content_fingerprint<>o.content_fingerprint or
   app_private.chem_choice_repetition_state(to_jsonb(n),jsonb_build_array(to_jsonb(o)||jsonb_build_object('study_date','2026-10-01','answered_at','2026-10-01T00:00:00+08:00','correct',true,'uncertain',false)),date '2026-10-01')->>'kind'<>'same_day_or_pending'
   or app_private.chem_choice_repetition_state(to_jsonb(n),jsonb_build_array(to_jsonb(o)||jsonb_build_object('study_date','2026-09-30','answered_at','2026-09-30T00:00:00+08:00','correct',true,'uncertain',false)),date '2026-10-01')->>'kind'<>'due_review') then raise exception 'Revision would be mistaken for a new original instead of retaining its review history';end if;
 if (select count(*) from app_private.chem_teaching_ready_questions q join h1_parent_review_input x on x.new_id=q.id where app_private.chem_choice_parent_identity(to_jsonb(q))=x.source_key)<>5 then raise exception 'Five source-reviewed identifiable questions not ready';end if;
 if exists(select 1 from app_private.chem_teaching_ready_questions q join h1_parent_review_input x on x.old_id=q.id) then raise exception 'Superseded old question remains deliverable';end if;
 if exists(select 1 from public.chem_questions q join h1_parent_old_questions b on b.id=q.id where to_jsonb(q)-array['usable_for_review','usable_for_class_quiz','usable_for_exam_sprint','usable_for_demo','updated_at']<>b.row_data) then raise exception 'Original question or identity changed';end if;
 if exists((select to_jsonb(a) from public.chem_attempt_answers a join h1_parent_review_input x on x.old_id=a.question_id except select to_jsonb(a) from h1_parent_old_answers a)
 union all (select to_jsonb(a) from h1_parent_old_answers a except select to_jsonb(a) from public.chem_attempt_answers a join h1_parent_review_input x on x.old_id=a.question_id)) then raise exception 'Old answers changed';end if;
 if exists((select to_jsonb(a) from app_private.chem_question_answer_locks a join h1_parent_review_input x on x.old_id=a.question_id except select to_jsonb(a) from h1_parent_old_locks a)
 union all (select to_jsonb(a) from h1_parent_old_locks a except select to_jsonb(a) from app_private.chem_question_answer_locks a join h1_parent_review_input x on x.old_id=a.question_id)) then raise exception 'Old answer locks changed';end if;
end $qa$;
select q.id,q.concept_key,q.parent_source_item_key,app_private.chem_question_item_delivery_review_ready(q.id) item_review_ready
from app_private.chem_teaching_ready_questions q join h1_parent_review_input x on x.new_id=q.id order by q.concept_key;
commit;
